cd /srv/agent-change; python3 -I - <<'EOF'
import json,collections
S={}
for r in ['r1','r2']:
    d=json.load(open(f'result-{r}.json'))
    ev=[e for e in d['traceEvents'] if e.get('ph')=='X']
    S[r]=set(e['name'] for e in ev)
    print(r, [e for e in ev if 'args' in e][:3])
    for e in ev:
        if e['name'] in ('_io.open','posix.open','_write_atomic','_io.open_code'):
            # find parent chain
            par=[p['name'] for p in ev if p['ts']<=e['ts'] and p['ts']+p['dur']>=e['ts']+e['dur'] and p is not e]
            print('  ',e['name'],par[-2:])
    if r=='r2':
        cnt=collections.Counter()
        for e in ev:
            if e['name'].startswith('discount_percent'):
                for p in ev:
                    if p['name'].split(' ')[0] in ('invoice_total','refund_amount') and p['ts']<=e['ts'] and p['ts']+p['dur']>=e['ts']+e['dur']:
                        cnt[p['name']]+=1
        print(cnt)
print(sorted(S['r2']-S['r1']))
EOF

